import { Element as SlateElement, Text } from 'slate'

/**
 * 获取第一个 text-node 的颜色
 * @param elem elem
 */
export function getListItemStyle(elem: SlateElement): {color:string;fontSize:string;bgColor?: string;bold:boolean;underline:boolean;through:boolean;italic:boolean;}|undefined {
  const children = elem.children || []
  const length = children.length

  if (length === 0) { return undefined }

  let firstTextNode

  for (let i = 0; i < length; i += 1) {
    if (firstTextNode) { break } // 已找到第一个 text-node ，则退出
    const child = children[i]

    if (Text.isText(child)) { firstTextNode = child }
  }

  if (firstTextNode == null) { return undefined }
  return firstTextNode
}

